      // Find messages for the selected channel from messageDataProp
      const channelMessages = this.messageDataProp.find(item => item.topic === this.selectedChannel.team_topic_id);
      if (channelMessages && channelMessages.data) {
        // Sort by creation date (newest first) and return unique messages
        const uniqueMessages = Array.from(new Map(channelMessages.data.map(item => [item.msg_id, item])).values());
        return uniqueMessages.sort((a, b) => new Date(b.msg_created_on) - new Date(a.msg_created_on));
